function model(p) {
  // One day of an AI agent's traffic in 48 half-hour buckets. Latency is seeded log-normal noise around a baseline that
  // rises with load; at the change hour a prompt or model change drifts latency up and errors up over about two hours.
  // A control chart on the half-hour median flags the first bucket outside mean +/- k sigma of the first six hours.
  const traffic = Math.max(100, Math.min(2000, Math.round(p.traffic / 100) * 100));
  const changeHour = Math.max(8, Math.min(20, Math.round(p.changeHour)));
  const k = Math.max(2, Math.min(4, Math.round(p.threshold * 2) / 2));
  let seed = 20261004 + traffic;
  const rnd = () => { seed |= 0; seed = seed + 0x6D2B79F5 | 0; let t = Math.imul(seed ^ seed >>> 15, 1 | seed); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; };
  const gauss = () => { const u = Math.max(1e-9, rnd()), v = rnd(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v); };
  const load = Math.max(0, (traffic - 1200) / 800); // queueing above about 1,200 requests an hour
  const muBase = Math.log(1.6) + 0.35 * load, sigma = 0.35, SAMPLES = 40;
  const drift = h => h < changeHour ? 0 : 1 - Math.exp(-(h - changeHour) / 1.5);
  const label = h => String(Math.floor(h)).padStart(2, '0') + ':' + (h % 1 ? '30' : '00');
  const buckets = [];
  for (let i = 0; i < 48; i++) {
    const hour = i / 2, d = drift(hour), mu = muBase + 0.45 * d;
    const samples = Array.from({ length: SAMPLES }, () => +Math.exp(mu + sigma * gauss()).toFixed(2)).sort((a, b) => a - b);
    const q = f => samples[Math.min(SAMPLES - 1, Math.floor(f * SAMPLES))];
    const requests = Math.round(traffic / 2 * (0.75 + 0.5 * (0.5 + 0.5 * Math.sin((hour - 6) / 24 * 2 * Math.PI))));
    const errRate = +Math.max(0, 0.01 + 0.05 * d + 0.004 * gauss()).toFixed(4);
    buckets.push({ i, hour, label: label(hour), requests, errors: Math.round(requests * errRate), errRate, p50: q(0.5), p95: q(0.95), mean: +(samples.reduce((a, s) => a + s, 0) / SAMPLES).toFixed(2), samples, drift: +d.toFixed(3) });
  }
  // Limits from the first six hours (12 buckets), which are always before the change
  const base = buckets.slice(0, 12), stat = arr => { const m = arr.reduce((a, v) => a + v, 0) / arr.length; return { mean: m, sd: Math.sqrt(arr.reduce((a, v) => a + (v - m) ** 2, 0) / (arr.length - 1)) }; };
  const L = stat(base.map(b => b.p50)), E = stat(base.map(b => b.errRate));
  const limits = { k, mean: +L.mean.toFixed(3), sd: +L.sd.toFixed(3), ucl: +(L.mean + k * L.sd).toFixed(3), lcl: +Math.max(0, L.mean - k * L.sd).toFixed(3),
    errMean: +E.mean.toFixed(4), errSd: +E.sd.toFixed(4), errUcl: +(E.mean + k * E.sd).toFixed(4) };
  buckets.forEach(b => { b.breach = b.i >= 12 && (b.p50 > limits.ucl || b.p50 < limits.lcl); b.errBreach = b.i >= 12 && b.errRate > limits.errUcl; });
  const first = buckets.find(b => b.breach) || null, firstErr = buckets.find(b => b.errBreach && b.hour >= changeHour) || null;
  const firstAfter = buckets.find(b => b.breach && b.hour >= changeHour) || null; // the detection; earlier breaches are false alarms
  const detectDelay = firstAfter ? +(firstAfter.hour - changeHour).toFixed(1) : null;
  const falseAlarms = buckets.filter(b => b.breach && b.hour < changeHour).length;
  // Pooled distributions for the violin and ridge versions: eight three-hour windows
  const windows = Array.from({ length: 8 }, (_, w) => { const bs = buckets.slice(w * 6, w * 6 + 6), s = bs.flatMap(b => b.samples).sort((a, b) => a - b);
    return { w, from: w * 3, to: w * 3 + 3, label: label(w * 3) + '–' + label(w * 3 + 3), samples: s, p50: s[Math.floor(s.length / 2)], p95: s[Math.floor(0.95 * s.length)], after: w * 3 >= changeHour, straddles: w * 3 < changeHour && w * 3 + 3 > changeHour }; });
  const before = buckets.filter(b => b.hour < changeHour).flatMap(b => b.samples), after = buckets.filter(b => b.hour >= changeHour + 2).flatMap(b => b.samples);
  const med = s => { const a = s.slice().sort((x, y) => x - y); return a.length ? a[Math.floor(a.length / 2)] : 0; };
  const shift = { beforeP50: +med(before).toFixed(2), afterP50: +med(after).toFixed(2) };
  shift.pct = shift.beforeP50 ? Math.round(100 * (shift.afterP50 - shift.beforeP50) / shift.beforeP50) : 0;
  const steps = [
    { id: 'baseline', t: 0, hour: 0, title: 'A normal morning', note: 'Latency hovers around ' + limits.mean.toFixed(1) + ' s at the median; the first six hours set the control limits at ' + limits.lcl.toFixed(1) + ' to ' + limits.ucl.toFixed(1) + ' s (mean ± ' + k + ' σ).' + (falseAlarms ? ' At ' + k + ' σ the limits are tight enough that ordinary noise trips them: ' + falseAlarms + ' false alarm' + (falseAlarms > 1 ? 's' : '') + ' before anything changed.' : '') },
    { id: 'change', t: changeHour, hour: changeHour, title: 'A change ships at ' + label(changeHour), note: 'A prompt or model change goes live. Nothing alerts: the next few minutes look like noise.' },
    { id: 'breach', t: firstAfter ? firstAfter.hour : 23, hour: firstAfter ? firstAfter.hour : 23, title: firstAfter ? 'Outside the limits at ' + firstAfter.label : 'No breach after the change', note: firstAfter ? 'The half-hour median crosses ' + limits.ucl.toFixed(1) + ' s, ' + detectDelay + ' h after the change. The error rate ' + (firstErr ? 'crosses its own limit at ' + firstErr.label + '.' : 'has not crossed its limit yet.') : 'The drift stays inside mean ± ' + k + ' σ all day.' },
    { id: 'sowhat', t: 22.5, hour: 22.5, title: 'So what for the team', note: 'The median moved from ' + shift.beforeP50 + ' s to ' + shift.afterP50 + ' s (' + (shift.pct >= 0 ? '+' : '') + shift.pct + ' %). A dashboard of averages hides this for hours; limits and distributions show it as a shape change.' }
  ];
  const summary = (firstAfter ? 'Breach at ' + firstAfter.label + ', ' + detectDelay + ' h after the ' + label(changeHour) + ' change' : 'No breach after the ' + label(changeHour) + ' change') + '; median ' + shift.beforeP50 + ' s → ' + shift.afterP50 + ' s, error rate ' + (100 * limits.errMean).toFixed(1) + ' % → ' + (100 * buckets[47].errRate).toFixed(1) + ' %' + (falseAlarms ? '; ' + falseAlarms + ' false alarm' + (falseAlarms > 1 ? 's' : '') + ' before the change.' : '; no false alarms.');
  return { traffic, changeHour, changeLabel: label(changeHour), k, buckets, limits, first, firstAfter, firstErr, detectDelay, falseAlarms, windows, shift, steps, duration: 24, markers: steps.map(s => s.t), summary };
}

