function check(p) {
  const m = model(p), L = m.limits;
  // Recompute the limits and the first breach independently from the buckets
  const base = m.buckets.slice(0, 12).map(b => b.p50), mean = base.reduce((a, v) => a + v, 0) / base.length;
  const sd = Math.sqrt(base.reduce((a, v) => a + (v - mean) ** 2, 0) / (base.length - 1));
  const ucl = mean + m.k * sd, lcl = Math.max(0, mean - m.k * sd);
  const limitsOk = Math.abs(ucl - L.ucl) < 0.01 && Math.abs(lcl - L.lcl) < 0.01;
  const mine = m.buckets.find(b => b.i >= 12 && (b.p50 > ucl + 1e-9 || b.p50 < lcl - 1e-9)) || null;
  const firstOk = (mine === null && m.first === null) || (mine && m.first && mine.i === m.first.i);
  // Every flagged bucket really is outside the limits, and none before the baseline window ends
  const flagsOk = m.buckets.every(b => b.breach === (b.i >= 12 && (b.p50 > L.ucl || b.p50 < L.lcl)));
  // Baseline is before the change, the drift only starts at the change, and latency and errors are higher after it
  const baselineClean = m.buckets.slice(0, 12).every(b => b.hour < m.changeHour && b.drift === 0);
  const after = m.buckets.filter(b => b.hour >= m.changeHour + 2), before = m.buckets.filter(b => b.hour < m.changeHour);
  const avg = (arr, f) => arr.reduce((a, b) => a + f(b), 0) / arr.length;
  const worse = avg(after, b => b.p50) > avg(before, b => b.p50) && avg(after, b => b.errRate) > avg(before, b => b.errRate);
  const samplesOk = m.buckets.every(b => b.samples.length === 40 && b.samples.every((s, i) => s > 0 && (i === 0 || s >= b.samples[i - 1])));
  const afterOk = (m.firstAfter === null) === !m.buckets.some(b => b.breach && b.hour >= m.changeHour) && (!m.firstAfter || m.detectDelay >= 0);
  const pass = limitsOk && firstOk && flagsOk && baselineClean && worse && samplesOk && afterOk;
  return {
    pass,
    detail: 'Limits ' + L.lcl.toFixed(2) + ' to ' + L.ucl.toFixed(2) + ' s from the first six hours' + (limitsOk ? '' : ' (recomputed differently)') + '; detection ' + (m.firstAfter ? 'at ' + m.firstAfter.label + ', ' + m.detectDelay + ' h after the change' : 'none') + (m.falseAlarms ? ', ' + m.falseAlarms + ' false alarm(s) before it' : '') + (firstOk ? '' : ' (disagrees with a recount)') +
      '; median after the change ' + m.shift.afterP50 + ' s vs ' + m.shift.beforeP50 + ' s before' + (worse ? '.' : ' (not worse).')
  };
}
